// ─── File: UploadDemo.java ───
// Runnable demo of the control plane. Each class would be its own file.
package com.bank.upload;

import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class UploadDemo {
    private static final Logger log = Logger.getLogger(UploadDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        long maxSize = 200L * 1024 * 1024;              // 200 MB
        PresignService presign = new PresignService("nbi-loan-documents", 300);
        TokenBucketRateLimiter limiter = new TokenBucketRateLimiter(10); // 10/min/user
        MetadataQueue queue = new MetadataQueue();
        UploadService service = new UploadService(maxSize, presign, limiter, queue);

        // Start a background scan worker that drains the metadata queue
        ScanWorker worker = new ScanWorker(queue);
        Thread workerThread = new Thread(worker, "scan-worker");
        workerThread.start();

        // Scenario 1: Rajesh uploads a 150 MB property file — issue presigned URL
        try {
            UploadTicket t1 = service.requestUpload(new UploadRequest(
                    "SAV2001", "property_deed.pdf", 150L * 1024 * 1024, "application/pdf"));
            log.info(() -> "TICKET for Rajesh: key=" + t1.storageKey + " url=" + t1.presignedUrl);
        } catch (Exception e) { log.severe("Rajesh upload failed: " + e.getMessage()); }

        // Scenario 2: oversized 500 MB file — rejected before any URL is issued
        try {
            service.requestUpload(new UploadRequest(
                    "CUR3001", "huge_video.mp4", 500L * 1024 * 1024, "video/mp4"));
        } catch (FileTooLargeException e) { log.severe("Priya oversized rejected: " + e.getMessage()); }

        // Scenario 3: rate limit — Rajesh fires 12 quick requests, last ones rejected
        for (int i = 0; i < 12; i++) {
            try {
                service.requestUpload(new UploadRequest(
                        "SAV2001", "statement_" + i + ".pdf", 1024L * 1024, "application/pdf"));
            } catch (RateLimitedException e) {
                log.warning("Rate limited request #" + i + ": " + e.getMessage());
            }
        }

        Thread.sleep(300);          // let worker process the queue
        worker.stop();
        workerThread.join(500);
    }
}

