// ─── service/PresignService.java ───
// Mints short-lived presigned URLs. Real impl uses S3Presigner.
class PresignService {
    private final String bucket; private final long ttlSeconds;
    PresignService(String bucket, long ttlSeconds) { this.bucket = bucket; this.ttlSeconds = ttlSeconds; }
    UploadTicket presignPut(String userId, String filename) {
        String key = userId + "/" + UUID.randomUUID() + "/" + filename;
        String url = "https://" + bucket + ".s3.amazonaws.com/" + key
                + "?X-Amz-Expires=" + ttlSeconds + "&X-Amz-Signature=SIMULATED";
        return new UploadTicket(key, url, Instant.now().plusSeconds(ttlSeconds));
    }
}

// ─── ratelimit/TokenBucketRateLimiter.java ───
// Simple per-user token bucket: N tokens per minute.
class TokenBucketRateLimiter {
    private final int capacity;
    private final Map<String, Integer> tokens = new ConcurrentHashMap<>();
    TokenBucketRateLimiter(int perMinute) { this.capacity = perMinute; }
    synchronized boolean tryAcquire(String userId) {
        int left = tokens.getOrDefault(userId, capacity);
        if (left <= 0) return false;
        tokens.put(userId, left - 1);
        return true;
    }
}

// ─── queue/MetadataQueue.java ───
// Async queue decoupling fast upload path from slow scanning.
class MetadataQueue {
    private final BlockingQueue<FileMetadata> q = new LinkedBlockingQueue<>();
    void publish(FileMetadata m) { q.offer(m); }
    FileMetadata poll(long ms) throws InterruptedException { return q.poll(ms, TimeUnit.MILLISECONDS); }
}

// ─── queue/ScanWorker.java ───
// Background worker: virus-scan, verify magic bytes, mark usable.
class ScanWorker implements Runnable {
    private static final Logger log = Logger.getLogger(ScanWorker.class.getName());
    private final MetadataQueue queue; private volatile boolean running = true;
    ScanWorker(MetadataQueue queue) { this.queue = queue; }
    void stop() { running = false; }
    public void run() {
        while (running) {
            try {
                FileMetadata m = queue.poll(100);
                if (m == null) continue;
                // simulate scan + MIME magic-byte verification
                m.status = "SCANNED_CLEAN";
                log.info("SCANNED " + m.storageKey + " (" + m.filename + ") → " + m.status);
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }
    }
}

// ─── service/UploadService.java ───
class UploadService {
    private static final Logger log = Logger.getLogger(UploadService.class.getName());
    private final long maxSize; private final PresignService presign;
    private final TokenBucketRateLimiter limiter; private final MetadataQueue queue;
    UploadService(long maxSize, PresignService presign, TokenBucketRateLimiter limiter, MetadataQueue queue) {
        this.maxSize = maxSize; this.presign = presign; this.limiter = limiter; this.queue = queue;
    }
    UploadTicket requestUpload(UploadRequest req) {
        if (!limiter.tryAcquire(req.userId))
            throw new RateLimitedException("too many uploads for " + req.userId);
        if (req.sizeBytes > maxSize)
            throw new FileTooLargeException("size " + req.sizeBytes + " exceeds max " + maxSize);
        UploadTicket ticket = presign.presignPut(req.userId, req.filename);
        // record metadata and enqueue for async scanning — NO file bytes here
        FileMetadata meta = new FileMetadata(ticket.storageKey, req.userId, req.filename, req.sizeBytes);
        queue.publish(meta);
        log.fine(() -> "issued presigned URL for " + req.userId + " key=" + ticket.storageKey);
        return ticket;
    }
}

