package com.bank.upload.controller;

import org.springframework.core.io.buffer.DataBuffer;
import org.springframework.http.codec.multipart.FilePart;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@RestController
@RequestMapping("/api/v1/uploads")
public class UploadController {

    // Control plane: issue a presigned URL (the normal, preferred path)
    @PostMapping
    public Mono<UploadTicket> createTicket(@RequestBody UploadRequest req) {
        return Mono.fromCallable(() -> uploadService.requestUpload(req));
    }

    // Streaming fallback: pipe bytes to S3 without buffering the whole file.
    // Flux<DataBuffer> delivers the body in chunks; backpressure keeps memory bounded.
    @PostMapping(path = "/stream", consumes = "multipart/form-data")
    public Mono<Void> stream(@RequestPart("file") Mono<FilePart> filePart) {
        return filePart.flatMap(part -> {
            Flux<DataBuffer> content = part.content();          // chunked, non-blocking
            return reactiveS3Client.upload(part.filename(), content); // backpressure honoured
        });
    }
}
